import{c as l,$ as s,Q as r,j as o,g as a,o as n,n as i,m as d}from"./chunks/framework.Ce_49mA8.js";const y=JSON.parse('{"title":"Аналитика и отчетность","description":"Сквозная финансовая аналитика, динамика выручки и расходов, расчет точки безубыточности и окупаемость времени мастера в ОмниКрафт ЕРП.","frontmatter":{"title":"Аналитика и отчетность","description":"Сквозная финансовая аналитика, динамика выручки и расходов, расчет точки безубыточности и окупаемость времени мастера в ОмниКрафт ЕРП.","datePublished":"2026-08-20","dateModified":"2026-11-14","order":5},"headers":[],"relativePath":"ru/docs/resources/analytics.md","filePath":"ru/docs/resources/analytics.md","lastUpdated":1794614400000}'),h={name:"ru/docs/resources/analytics.md"},c={id:"аналитика-и-финансовые-графики",tabindex:"-1"};function g(p,t,u,f,m,b){const e=s("DocIcon");return r(),o("div",null,[a("h1",c,[n(e,{name:"analytics"}),t[0]||(t[0]=i(" Аналитика и финансовые графики ",-1)),t[1]||(t[1]=a("a",{class:"header-anchor",href:"#аналитика-и-финансовые-графики","aria-label":'Permalink to "Аналитика и финансовые графики"'},"​",-1))]),t[2]||(t[2]=d('<p>Вкладка <strong>«Аналитика»</strong> служит единым командным центром и интерактивной приборной панелью вашего дела. Если журнал движения денег (ДДС) контролирует оперативную кассу, склад и мастерская — физические ресурсы, а отчет «Капитал» показывает совокупную рыночную стоимость бизнеса, то аналитика отвечает на главный стратегический вопрос создателя:</p><blockquote><p><strong>Насколько устойчиво развивается мое дело и какую реальную отдачу приносит каждый час вложенного труда?</strong></p></blockquote><p>Программа автоматически сводит воедино данные из всех рабочих контуров — журнала продаж, складских остатков сырья, закрытых заказ-нарядов и кассовых ордеров. На их основе формируются ключевые индикаторы эффективности и наглядные графики трендов.</p><hr><h2 id="три-ключевых-индикатора-здоровья-дела" tabindex="-1">Три ключевых индикатора здоровья дела <a class="header-anchor" href="#три-ключевых-индикатора-здоровья-дела" aria-label="Permalink to &quot;Три ключевых индикатора здоровья дела&quot;">​</a></h2><p>В верхней панели экрана расположены три информационные карточки, которые пересчитываются программой в режиме реального времени на основе всей накопленной истории операций.</p><h3 id="_1-среднии-чек-сделки" tabindex="-1">1. Средний чек сделки <a class="header-anchor" href="#_1-среднии-чек-сделки" aria-label="Permalink to &quot;1. Средний чек сделки&quot;">​</a></h3><p>Показывает средний объем выручки, приходящийся на одну завершенную операцию — проведенную розничную продажу или закрытый заказ-наряд.</p><ul><li><strong>Зачем контролировать:</strong> Индикатор отражает результативность вашей ценовой политики, наборов и сопутствующих предложений.</li><li><strong>Практическое применение:</strong> Если вы добавили фирменную упаковку, ввели подарочные комплекты или подняли расценки на услуги, рост среднего чека наглядно подтверждает правильность выбранного шага.</li></ul><h3 id="_2-точка-безубыточности-порог-стабильности" tabindex="-1">2. Точка безубыточности (Порог стабильности) <a class="header-anchor" href="#_2-точка-безубыточности-порог-стабильности" aria-label="Permalink to &quot;2. Точка безубыточности (Порог стабильности)&quot;">​</a></h3><p>Фундаментальный порог финансовой выживаемости мастерской или сервисного центра. Программа анализирует постоянные и переменные расходы за последние полгода (включая аренду, рекламу, связь, расходники и линейную амортизацию оборудования) и делит их на среднюю прибыль с одной сделки.</p><ul><li><strong>Смысл показателя:</strong> Число показывает <strong>минимальное количество изделий или заказ-нарядов в месяц</strong>, необходимое для работы строго «в ноль» без образования кассовых разрывов.</li><li><strong>Экономический ориентир:</strong> Всё, что изготовлено или выполнено сверх этого порогового значения, формирует чистую прибыль владельца.</li></ul><h3 id="_3-окупаемость-рабочего-времени" tabindex="-1">3. Окупаемость рабочего времени <a class="header-anchor" href="#_3-окупаемость-рабочего-времени" aria-label="Permalink to &quot;3. Окупаемость рабочего времени&quot;">​</a></h3><p>Специализированная метрика <strong>ОмниКрафт ЕРП</strong>, созданная специально для прикладных мастеров, ремесленников и сервисных специалистов.</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Экономическая модель</span><div class="formula-heading">Окупаемость рабочего времени мастера</div></div><div class="formula-equation-box"><div class="math-line"><span class="math-var">Ставка окупаемости (₽/час)</span><span class="math-op">=</span><span class="math-fraction"><span class="math-numerator">Суммарная чистая прибыль</span><span class="math-denominator">Отработанные нормо-часы</span></span></div></div><div class="formula-card-bottom"><p>Показывает реальную чистую отдачу за каждый час работы за верстаком с учётом списания сырья, накладных расходов и амортизации.</p></div></div><ul><li><strong>Смысл показателя:</strong> Значение отражает чистую отдачу за <strong>один час</strong> непосредственной работы за верстаком или сервисным столом.</li><li><strong>Практическая польза:</strong> Расчет вскрывает скрытые ловушки трудозатрат. Нередко сложное штучное изделие с высокой ценой приносит всего 350 рублей за час из-за многодневной кропотливой сборки, тогда как компактный типовой предмет дает отдачу в 1 800 рублей в час. Это прямой сигнал к пересмотру прейскуранта или оптимизации конструкции изделия.</li></ul><hr><h2 id="финансовыи-пульс-тренды-за-полгода" tabindex="-1">Финансовый пульс: Тренды за полгода <a class="header-anchor" href="#финансовыи-пульс-тренды-за-полгода" aria-label="Permalink to &quot;Финансовый пульс: Тренды за полгода&quot;">​</a></h2><p>Линейный график раскрывает финансовую динамику мастерской за последние 6 месяцев. Он объединяет три взаимосвязанные линии:</p><ul><li>🟢 <strong>Выручка:</strong> Фактический объем денежных средств, поступивший от клиентов и розничных покупателей.</li><li>🟠 <strong>Совокупные затраты:</strong> Полная себестоимость израсходованных материалов по методу скользящей средней стоимости (МАК) плюс операционные расходы из ДДС и начисленный линейный износ оборудования из вкладки «Мастерская».</li><li>🔵 <strong>Чистая прибыль:</strong> Реальный финансовый остаток каждого месяца (разница между выручкой и полными затратами).</li></ul><div class="tip custom-block"><p class="custom-block-title">Опасный эффект «финансовых ножниц»</p><p>Внимательно следите за расхождением между зеленой линией выручки и оранжевой линией затрат. Если выручка стабильно растет, а кривая прибыли прижимается вниз или падает — вы столкнулись со снижением маржинальности.</p><p>Это прямой сигнал о скрытом росте закупочных цен на сырье у поставщиков, удорожании доставки партий или расползании накладных расходов. Время провести ревизию закупочных цен на Складе и заложить новые нормативы в Калькулятор.</p></div><hr><h2 id="структура-выручки-локомотивы-продаж-и-авс-анализ" tabindex="-1">Структура выручки: Локомотивы продаж и АВС-анализ <a class="header-anchor" href="#структура-выручки-локомотивы-продаж-и-авс-анализ" aria-label="Permalink to &quot;Структура выручки: Локомотивы продаж и АВС-анализ&quot;">​</a></h2><p>Круговая диаграмма наглядно демонстрирует, какие именно изделия или типы услуг формируют основной денежный поток вашего дела.</p><p>Система автоматически ранжирует ассортимент, выделяя <strong>пять ведущих позиций</strong>, приносящих наибольшую выручку, а все остальные позиции объединяет в сектор «Прочие».</p><table class="craft-matrix-table"><thead><tr><th style="width:40%;">Сегмент ассортимента</th><th style="width:60%;">Вклад в денежный поток</th></tr></thead><tbody><tr><td><strong>Группа лидеров (Топ-5)</strong></td><td>Локомотивы продаж: формируют 70–85% совокупного денежного потока и чистой прибыли.</td></tr><tr><td><strong>Сектор «Прочие»</strong></td><td>Ассортиментный шлейф, индивидуальные эксперименты и сопутствующие аксессуары.</td></tr></tbody></table><h3 id="управленческие-выводы-по-диаграмме" tabindex="-1">Управленческие выводы по диаграмме: <a class="header-anchor" href="#управленческие-выводы-по-диаграмме" aria-label="Permalink to &quot;Управленческие выводы по диаграмме:&quot;">​</a></h3><ol><li><strong>Защита локомотивов:</strong> Позиции из группы лидеров нельзя допускать до дефицита на складе. Закупка сырья, фурнитуры и запчастей для них планируется в первую очередь.</li><li><strong>Отсечение балласта:</strong> Товары или услуги с микроскопической долей в выручке требуют пристального внимания. Если при низкой доле продаж они требуют редких материалов и сложной настройки оборудования, имеет смысл вывести их из постоянного прейскуранта.</li></ol><hr><h2 id="матрица-цеховых-решении" tabindex="-1">Матрица цеховых решений <a class="header-anchor" href="#матрица-цеховых-решении" aria-label="Permalink to &quot;Матрица цеховых решений&quot;">​</a></h2><p>Настоящая польза аналитики проявляется при одновременном сопоставлении нескольких индикаторов:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Показания на экране</th><th style="text-align:left;">Диагноз состояния</th><th style="text-align:left;">Рекомендуемое действие мастера</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Низкая окупаемость времени</strong> при высоком среднем чеке</td><td style="text-align:left;">Сложная ручная работа на износ, неоправданно съедающая рабочие часы</td><td style="text-align:left;">Пересмотреть нормы времени, поднять цену в Калькуляторе или упростить технологические узлы</td></tr><tr><td style="text-align:left;"><strong>Точка безубыточности растет</strong> от месяца к месяцу</td><td style="text-align:left;">Разрастание постоянных затрат (аренда, подписки, логистика)</td><td style="text-align:left;">Открыть вкладку ДДС, провести ревизию регулярных расходов и отсечь непроизводственные траты</td></tr><tr><td style="text-align:left;"><strong>Структура выручки</strong> зависит от одного товара (&gt;75%)</td><td style="text-align:left;">Уязвимость дела перед сменой потребительского спроса или дефицитом сырья</td><td style="text-align:left;">Разработать смежные модификации, запустить дополнительные варианты в Калькуляторе</td></tr><tr><td style="text-align:left;"><strong>Выручка растет</strong>, а чистая прибыль стагнирует</td><td style="text-align:left;">Эффект финансовых ножниц: опережающий рост себестоимости материалов</td><td style="text-align:left;">Проверить средневзвешенные цены на Складе, обновить стоимость доставки в партиях</td></tr></tbody></table><hr><h2 id="ознакомительныи-демо-режим-и-первыи-запуск" tabindex="-1">Ознакомительный Демо-режим и первый запуск <a class="header-anchor" href="#ознакомительныи-демо-режим-и-первыи-запуск" aria-label="Permalink to &quot;Ознакомительный Демо-режим и первый запуск&quot;">​</a></h2><p>При первом запуске программы в пустом пространстве вкладка «Аналитика» встречает аккуратным экраном ожидания с подсказками:</p><ul><li><strong>Кнопка перехода к операциям:</strong> Прямой переход в журнал продаж или заказ-наряды для оформления первых сделок.</li><li><strong>Кнопка «Демо-режим»:</strong> Включает демонстрационный набор синтетических данных типовой мастерской. Это позволяет наглядно изучить поведение графиков, протестировать всплывающие подсказки и оценить логику расчетов до внесения собственной истории.</li></ul>',36))])}const _=l(h,[["render",g]]);export{y as __pageData,_ as default};
